import leaderboardData from '../data/leaderboard.json';
import playersData from '../data/players.json';
import playerStatsData from '../data/player-stats.json';
import ratingHistoryData from '../data/rating-history.json';
import playerDetailsData from '../data/player-details.json';
import matchesData from '../data/matches.json';
import { Player, Match, PlayerDetail } from '../types';

export const fetchLeaderboard = async (): Promise<Player[]> => {
  return leaderboardData.players as Player[];
};

export const fetchPlayers = async (): Promise<Player[]> => {
  return playersData.players as Player[];
};

export const fetchPlayerStats = async (): Promise<any[]> => {
  return playerStatsData.players;
};

export const fetchRatingHistory = async (): Promise<any[]> => {
  return ratingHistoryData.history;
};

export const fetchPlayerDetail = async (handle: string): Promise<PlayerDetail | null> => {
  const entry = (playerDetailsData as any)[handle];
  if (!entry) return null;
  return {
    ...entry.player,
    recent: entry.recent,
  };
};

export const fetchAllMatches = async (): Promise<Match[]> => {
  return matchesData.matches as Match[];
};
